const L=h=>{const c=i=>{const v=parseInt(h.slice(i,i+2),16)/255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4};return 0.2126*c(1)+0.7152*c(3)+0.0722*c(5)};
const R=(a,b)=>{const [x,y]=[L(a),L(b)].sort((p,q)=>q-p);return ((x+0.05)/(y+0.05)).toFixed(2)};
const test=(f,bs,n)=>bs.forEach(b=>console.log(R(f,b).padStart(6),f,'on',b,n));
test("#a35f0c",["#f6f7fa","#ffffff"],"ring light candidate");
test("#9a5a0a",["#f6f7fa","#ffffff"],"ring light candidate2");
test("#1b1e2b",["#e5484d"],"ink on destructive");
test("#ffffff",["#c7353a"],"white on darker destr");
test("#10121c",["#f2585d"],"dark ink on destr dark");
test("#1b1e2b",["#4f7cf0"],"ink on info");
test("#10121c",["#6f97f6"],"dark ink on info dark");
test("#1b1e2b",["#3ecb84","#2fb574"],"ink on success dark");
test("#10121c",["#3ecb84","#f0983f"],"dark ink on success/warn dark");
test("#1b1e2b",["#e4802b"],"ink on warning light");
'

