cd D:/Repos/angular-jig && node -e '
const L=h=>{const c=i=>{const v=parseInt(h.slice(i,i+2),16)/255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4};return 0.2126*c(1)+0.7152*c(3)+0.0722*c(5)};
const R=(a,b)=>{const [x,y]=[L(a),L(b)].sort((p,q)=>q-p);return ((x+0.05)/(y+0.05)).toFixed(2)};
for (const [f,b,n] of [["#ffffff","#3a68d8","white on info a"],["#ffffff","#3d6ee0","white on info b"],["#1b1e2b","#3d6ee0","ink on info b"],["#9aa0b4","#1e2231","dark muted fg"],["#9aa0b4","#0e1018","dark muted on bg"],["#8b90a6","#10121c","sidebar muted dark"],["#5b6072","#ffffff","light muted on card"],["#1b1e2b","#f6f7fa","fg on bg"],["#1b1e2b","#eef0f6","fg on muted"],["#1b1e2b","#e4802b","warn fg"],["#eceef6","#2a2f45","sidebar active"],["#eceef6","#20263c","sidebar active dark"]]) console.log(R(f,b).padStart(6), n);
'

