@layer theme, base, components, utilities;
@import 'tailwindcss/theme.css' layer(theme);
@import 'tailwindcss/preflight.css' layer(base);
@import 'tailwindcss/utilities.css';

@import '@spartan-ng/brain/hlm-tailwind-preset.css';
/* You can add global styles to this file, and also import other style files */

/*
 * Hero Ops Console palette. Roles from the capstone build spec map onto
 * spartan's own tokens; the semantic and rail roles without a spartan
 * counterpart get their own tokens, exposed to Tailwind below.
 *
 * Deviations from the spec table, each forced by the WCAG arithmetic the
 * contrast gate runs (harness/gate/check-contrast.mjs):
 *   - light --primary-foreground is ink, not #ffffff: white on #d8891a is 2.80:1.
 *   - light --destructive is #c7353a, not #e5484d: white on #e5484d is 3.91:1.
 *   - light --info is #3d6ee0, not #4f7cf0: white on #4f7cf0 is 3.84:1.
 *   - light --ring is #a35f0c, not amber @ 35%: 35% amber over white is 1.4:1,
 *     and a translucent colour cannot be read by the gate or by a user.
 *   - dark --ring is solid amber, not amber @ 40%, for the same reason.
 */
:root {
  color-scheme: light;

  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.625rem;

  /* page and text */
  --background: #f6f7fa;
  --foreground: #1b1e2b;
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;

  /* action colour (amber) */
  --primary: #d8891a;
  --primary-foreground: #1b1e2b;

  /* muted surface and its text; spartan's accent is the subtle hover fill */
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;

  --destructive: #c7353a;
  --destructive-foreground: #ffffff;
  --border: #e4e7ef;
  --input: #e4e7ef;
  --ring: #a35f0c;

  /* semantic status: these carry meaning, so they never stand in for the accent */
  --success: #2fb574;
  --success-foreground: #1b1e2b;
  --warning: #e4802b;
  --warning-foreground: #1b1e2b;
  --info: #3d6ee0;
  --info-foreground: #ffffff;

  /* navigation rail: dark in both themes */
  --sidebar: #1e2233;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #f5b843;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #2a2f45;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #2a2f45;
  --sidebar-ring: #f5b843;
  --sidebar-muted: #9aa0b4;
}

:root.dark {
  color-scheme: dark;

  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);

  --background: #0e1018;
  --foreground: #eceef6;
  --card: #171a26;
  --card-foreground: #eceef6;
  --popover: #171a26;
  --popover-foreground: #eceef6;

  --primary: #f5b843;
  --primary-foreground: #241a05;

  --secondary: #1e2231;
  --secondary-foreground: #eceef6;
  --muted: #1e2231;
  --muted-foreground: #9aa0b4;
  --accent: #1e2231;
  --accent-foreground: #eceef6;

  --destructive: #f2585d;
  --destructive-foreground: #10121c;
  --border: #272b3b;
  --input: #272b3b;
  --ring: #f5b843;

  --success: #3ecb84;
  --success-foreground: #10121c;
  --warning: #f0983f;
  --warning-foreground: #10121c;
  --info: #6f97f6;
  --info-foreground: #10121c;

  --sidebar: #10121c;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #f5b843;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #20263c;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #20263c;
  --sidebar-ring: #f5b843;
  --sidebar-muted: #8b90a6;
}

/* Expose the tokens that spartan's preset does not map, so utilities such as
   text-success or bg-info resolve to the same variables as everything else. */
@theme inline {
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-sidebar-muted: var(--sidebar-muted);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

